let answers=Array(16).fill(null),index=0,current='home',lastResult;try{const a=JSON.parse(localStorage.getItem('guanji-answers'));if(Array.isArray(a)&&a.length===16&&a.every(v=>v===null||Number.isInteger(v)&&v>=0&&v<4))answers=a}catch{}
function save(){try{localStorage.setItem('guanji-answers',JSON.stringify(answers))}catch{}}
const art=`<svg viewBox="0 0 200 235" xmlns="http://www.w3.org/2000/svg" aria-label="古代文人山水插画" role="img"><circle cx="104" cy="111" r="87" fill="#e3e5d5"/><path d="M4 186Q40 135 64 168Q100 111 135 159Q170 131 198 174V222H4Z" fill="#cbd3bc"/><path d="M10 206Q48 160 87 190Q139 153 193 203V229H10Z" fill="#b7c4a5"/><path d="M149 55l19-16m-15 25 24-13" stroke="#8a9a7a" fill="none"/><circle cx="59" cy="57" r="17" fill="#f4f1dc"/><path d="M49 219q5-68 33-83h38q34 20 38 83" fill="#536957"/><path d="M80 140l20 43 23-44-8-14H88Z" fill="#ede7d1"/><path d="M84 132q-20-14-15-42 1-29 30-31 30 3 31 31 3 25-16 43l-14 9Z" fill="#d3b58a"/><path d="M69 95q-10-36 28-39 37-4 35 37l-13-22-37 8Z" fill="#333f35"/><path d="M68 68l-5-24 30-9 36 10 6 25Z" fill="#354b3e"/><path d="M56 70q46-9 89-1l-5 9q-39-5-80 2Z" fill="#354b3e"/><path d="M83 110q16 11 33-1l-4 24-12 23-12-22Z" fill="#495241"/><path d="M82 93l9-2m17 0 9 2" stroke="#5e5d46" stroke-width="2"/><path d="M96 95l-2 10 7 1" fill="none" stroke="#b39168"/><path d="M63 165l35 39 37-42m-57-9-8 47 29 20" fill="none" stroke="#84917a" stroke-width="2"/><path d="M108 186l42-10-3 33-39 11Z" fill="#e9dfc2" stroke="#8b916f"/><path d="M114 192l28-8m-28 15 26-8m-26 15 24-8" stroke="#a6a68a"/><path d="M49 219h110" stroke="#65785d"/><path d="M23 139l-5-41m3 17-10-10m11 22 11-12" stroke="#8b9d7e" fill="none"/></svg>`;
function home(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">A LITTLE HISTORY. A LOT OF YOU.</div><h1>穿越千年，<br>遇见另一个<em>自己。</em></h1><p class="intro">历史上，早有人带着与你相似的性格，走过一生。<br>循着你的日常选择，找到那位与你同频的历史人物。</p><button class="primary" id="start">${answers.some(a=>a!==null)?'继续我的探索':'开启我的探索'} <span>↗</span></button><div class="hero-meta"><span>16 道情境选择</span><span>约 3 分钟</span><span>无需登录</span></div></div><div class="art"><div class="art-ring"></div><span class="float-note top"><i></i>你的性格，自有回响</span><div class="portrait-card back">千年之间 · 总有同频</div><div class="portrait-card front"><div class="portrait-top"><span>HISTORICAL PORTRAIT</span><span>NO. 001</span></div>${art}<div class="portrait-name">苏轼<small>旷达 · 自在 · 热爱</small></div></div><span class="seal">以史<br>观己</span><span class="float-note bottom">「 人间有味是清欢 」</span></div></section><section class="below"><div class="feature"><span class="feature-num">01</span><div><h3>从日常出发</h3><p>没有标准答案，选择最像你的那一个。<br>在熟悉的情境里，看见真实的自己。</p></div></div><div class="feature"><span class="feature-num">02</span><div><h3>用八个维度，认识自己</h3><p>决断、共情、开创、洞察……<br>每一种倾向，都是独特的性格切面。</p></div></div><div class="feature"><span class="feature-num">03</span><div><h3>收获一份专属人物档案</h3><p>找到你的历史同频者。<br>读懂相似之处，也发现自己的可能。</p></div></div></section><p class="quiz-caption">500 份独立人物画像 · 八维选择匹配 · 遇见自己的独特底色</p>`}
function quiz(){const q=questions[index];return `<section class="screen"><div class="quiz-head"><button class="text-button" id="exit">← 返回首页</button><span>认识自己的一小步 <b>${String(index+1).padStart(2,'0')}</b> / 16</span></div><div class="progress"><i style="width:${(index+1)/16*100}%"></i></div><div class="question-card"><span class="q-index">Question ${String(index+1).padStart(2,'0')}</span><h1>${q[0]}</h1><p class="hint">凭第一感觉选择，选中后会自动进入下一题。</p><div class="options">${q.slice(1).map((o,i)=>`<button class="option ${answers[index]===i?'selected':''}" data-option="${i}" aria-pressed="${answers[index]===i}"><span>${'ABCD'[i]}</span>${o[0]}</button>`).join('')}</div><div class="q-actions"><button class="text-button" id="prev" ${index===0?'disabled':''}>← 上一题</button><span class="auto-hint" role="status">${index===15?'选中后生成画像':'选中后自动进入下一题'}</span></div></div><p class="quiz-caption">可返回上一题修改答案 · 选择后自动前进</p></section>`}
function normalize(values){const total=values.reduce((sum,v)=>sum+v,0);return values.map(v=>total?v/total:0)}
function scoreAnswers(values){const raw=Array(8).fill(0),max=Array(8).fill(0);questions.forEach((q,j)=>{for(let d=0;d<8;d++)if(q.slice(1).some(o=>o[1].includes(d)))max[d]+=3;const option=q[values[j]+1];option[1].forEach((d,k)=>raw[d]+=k===0?3:2)});return raw.map((v,i)=>max[i]?v/max[i]*100:0)}
function rankPeople(scores){const user=normalize(scores),dominant=user.indexOf(Math.max(...user));return people.map(p=>{const target=normalize(p.v);const distance=Math.sqrt(target.reduce((sum,v,i)=>sum+(v-user[i])**2,0));const dominantGap=Math.abs(target[dominant]-user[dominant]);const absoluteGap=target.reduce((sum,v,i)=>sum+Math.abs(v-user[i]),0);return{p,distance,dominantGap,absoluteGap,match:Math.round(Math.max(0,1-distance/Math.SQRT2)*100)}}).sort((a,b)=>a.distance-b.distance||a.dominantGap-b.dominantGap||a.absoluteGap-b.absoluteGap||a.p.id.localeCompare(b.p.id))}
function calculate(){const scores=scoreAnswers(answers);return{...rankPeople(scores)[0],scores:scores.map(Math.round)}}

function result(){lastResult=calculate();const{p,match,scores}=lastResult;return `<section class="screen"><div class="eyebrow">YOUR HISTORICAL SOULMATE</div><h1>原来，你的性格自有回响。</h1><p class="screen-sub">这一次，与历史里的另一个自己打个照面。</p><div class="result-layout"><div class="result-main"><div class="result-label">你的历史人物匹配画像</div><div class="match">${match}<small>%</small></div><span class="result-label">八维相似度 · 趣味参考</span><h1>${p.name}</h1><p>${p.era} · ${p.role}</p><p style="font-size:10px;color:#8c7baa">独立人物参数匹配 · 非人物真实心理测评</p><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="quote">“${p.line}”<small>画像寄语 · 创作演绎，非历史原话</small></div></div><div class="panel"><h2>你的八维性格切面</h2><p>只呈现本次选择倾向，不是能力高低。</p><div class="bars">${dims.map((d,i)=>`<div class="bar-row"><span>${d}</span><div class="bar-track"><i style="width:${scores[i]}%"></i></div><b>${scores[i]}</b></div>`).join('')}</div></div></div><div class="panel result-detail"><h2>01 · ${p.type}</h2><p>${p.desc}</p><h2 style="margin-top:24px">02 · 给此刻的你</h2><p>${p.advice}</p></div><div class="result-actions"><button class="primary" id="download">保存画像卡片 <span>↓</span></button><button class="secondary" id="review">回看我的选择</button><button class="text-button" id="restart">重新探索 ↗</button></div><p class="quiz-caption">相近的是部分处事方式，不代表经历、能力或价值相同。你不必成为任何人的翻版。</p></section>`}
function about(){return `<section class="screen"><div class="eyebrow">A MIRROR, NOT A LABEL</div><h1>借历史的一面镜，<br>看见自己的一束光。</h1><div class="about-panel"><h2>为什么是历史人物？</h2><p>那些跨越千年的故事里，藏着熟悉的勇气、犹豫、温柔与坚持。观己以历史人物为灵感，用日常情境中的选择，呈现你的处事倾向。</p><h2>画像如何产生？</h2><p>16 道题分别给决断、共情、开创、洞察、表达、经营、独立、担当八个维度累积权重，每位人物都单独维护八维参数、标签、专属解读与建议。答案按每道题的维度权重累积，并按各维度获得分数的机会校正；随后将答案和每个人物的八维向量分别归一为总和 1，比较欧氏距离，推荐距离最小的人物。全部 500 位人物都参与计算，不先分成八类，也不使用姓名、随机数或答案哈希挑选人物。相似度按 100 ×（1 − 距离 ÷ √2）计算，是这份创作配置下的向量接近程度，不是统计概率；同一组答案得到同一结果。完全同距时，先比较答案主导维度的差异，再比较各维度绝对差之和；仍相同时按固定人物编号排序。</p><h2>关于你，也关于隐私</h2><p>这是一个趣味自我探索工具，没有经过专业心理量表验证。人物参数依据代表作品、经历或传统记载作编辑性创作，未经心理量表验证，也不声称已逐条完成史料考证；包含经典叙事人物。人物画像不是历史定论，匹配不代表认可人物全部行为。画像寄语与建议为原创，不是历史原话。答案只尝试保存在当前浏览器；本地文件能否跨次保存取决于浏览器设置，不会上传到服务器；重新探索会清除本次记录。</p></div></section>`}
function render(view){cancelAdvance();current=view;$('#app').innerHTML=({home,quiz,result,about})[view]();document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));bind()}
function go(view){render(view);window.scrollTo({top:0,behavior:'instant'})}
let advanceTimer=null;
function cancelAdvance(){if(advanceTimer!==null){clearTimeout(advanceTimer);advanceTimer=null}}
function bind(){document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{
if(advanceTimer!==null)return;
answers[index]=+b.dataset.option;save();
document.querySelectorAll('[data-option]').forEach(option=>{const selected=+option.dataset.option===answers[index];option.classList.toggle('selected',selected);option.setAttribute('aria-pressed',String(selected));option.disabled=true});
const selectedIndex=index;
advanceTimer=setTimeout(()=>{advanceTimer=null;if(current!=='quiz'||index!==selectedIndex)return;if(index===15)go('result');else{index++;render('quiz')}},220);
});
if($('#start'))$('#start').onclick=()=>{index=answers.findIndex(a=>a===null);if(index<0)go('result');else go('quiz')};
if($('#exit'))$('#exit').onclick=()=>go('home');
if($('#prev'))$('#prev').onclick=()=>{cancelAdvance();if(index>0){index--;render('quiz')}};
if($('#review'))$('#review').onclick=()=>{index=0;go('quiz')};
if($('#restart'))$('#restart').onclick=()=>{answers=Array(16).fill(null);save();index=0;go('quiz')};
if($('#download'))$('#download').onclick=download}

function download(){const{p,match,scores}=lastResult;const c=document.createElement('canvas');c.width=900;c.height=1280;const x=c.getContext('2d');x.fillStyle='#f2eef7';x.fillRect(0,0,900,1280);x.fillStyle='#fffefa';x.fillRect(40,40,820,1200);x.textAlign='center';x.fillStyle='#8470a9';x.font='24px sans-serif';x.fillText('观己 · 你的历史人物画像',450,112);x.font='bold 100px sans-serif';x.fillText(match+'%',450,240);x.fillStyle='#2f3e36';x.font='bold 62px serif';x.fillText(p.name,450,330);x.font='24px sans-serif';x.fillText(p.era+' · '+p.type,450,386);x.fillStyle='#8e7aa8';x.font='22px sans-serif';x.fillText(p.tags.join('   /   '),450,438);x.font='25px serif';x.fillText('“'+p.line+'”',450,512);x.font='16px sans-serif';x.fillText('人物心声为创作演绎，非历史原话',450,551);x.textAlign='left';scores.forEach((v,i)=>{let y=635+i*57;x.fillStyle='#4b574d';x.font='22px sans-serif';x.fillText(dims[i],100,y);x.fillStyle='#eee9f4';x.fillRect(185,y-17,510,12);x.fillStyle='#9480b5';x.fillRect(185,y-17,510*v/100,12);x.fillText(String(v),730,y)});x.textAlign='center';x.fillStyle='#959489';x.font='18px sans-serif';x.fillText('选择契合度仅供趣味参考，不是能力或人生评分。',450,1145);x.fillText('每一种性格，都有自己的来处。',450,1185);const a=document.createElement('a');a.download='观己-'+p.name+'-人物画像.png';a.href=c.toDataURL('image/png');a.click();$('#toast').textContent='画像卡片已生成，请查看下载';$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600)}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();go('home')};render('home');


